H.background();
const cx = H.W * 0.42, cy = H.H * 0.55, R = Math.min(H.W, H.H) * 0.32;
const spd = P.spd, Rkm = P.R;
const omega = spd / Math.max(0.1, Rkm);
const ang = (omega * t) % (Math.PI * 2);
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 2 });
const px = cx + R * Math.cos(ang), py = cy - R * Math.sin(ang);
const vx = -Math.sin(ang), vy = -Math.cos(ang);
const aL = 18 + spd * 5;
H.arrow(px, py, px + vx * aL, py + vy * aL, { color: H.colors.warn, width: 4, head: 12 });
H.circle(px, py, 8, { fill: H.colors.accent2, stroke: H.colors.bg, width: 2 });
H.line(cx, cy, px, py, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
H.circle(cx, cy, 4, { fill: H.colors.ink });
const lapT = (2 * Math.PI * Rkm) / Math.max(0.1, spd);
H.text("Speed vs velocity", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("speed = " + spd.toFixed(1) + " m/s (constant)   velocity direction = " + (ang * 180 / Math.PI).toFixed(0) + " deg (always changing)   lap = " + lapT.toFixed(1) + " s", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "velocity (vector)", color: H.colors.warn }, { label: "radius", color: H.colors.violet }], H.W - 200, 28);
